    if (str == null || session == null || lb == null) {
        throw new IllegalArgumentException("Arguments cannot be null");
    }
    try {
        int length = str.length();
        int size = 0;
        for (int i = 0; i < length; i++) {
            char c = str.charAt(i);
            if (c < 0x80) {
                size += 1;
            } else if (c < 0x800) {
                size += 2;
            } else if (Character.isSurrogate(c)) {
                if (i + 1 < length) {
                    char nextChar = str.charAt(i + 1);
                    if (Character.isSurrogatePair(c, nextChar)) {
                        size += 4;
                        i++; // Skip the next character as it is part of the surrogate pair
                    } else {
                        throw new IllegalArgumentException("Invalid surrogate pair");
                    }
                } else {
                    throw new IllegalArgumentException("Invalid surrogate pair");
                }
