    if (neededCapacity > (this.data == null ? 0 : this.data.length)) {
        int newCapacity = (this.data == null ? 32 : this.data.length) * 2;
        while (newCapacity < neededCapacity) {
            newCapacity *= 2;
        }
        byte[] newData = new byte[newCapacity];
