private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null) {
        throw new IllegalArgumentException("Input list cannot be null");
    }

    List<Integer> suffixSum = new ArrayList<>();
    long totalSum = 0;
    long currentSuffixSum = 0;

    for (int i = bounds.size() - 1; i >= 0; i--) {
        if (bounds.get(i) == null) {
            throw new IllegalArgumentException("List elements cannot be null");
        }
        currentSuffixSum += bounds.get(i);
        suffixSum.add(0, (int) currentSuffixSum);
        totalSum += bounds.get(i);
    }

    return new Pair<>(suffixSum, totalSum);
}

